def dfs(x, y):
    if x < 0 or y < 0 or x >= rows or y >= cols or grid[x][y] != 'O':
        return
    grid[x][y] = 'S'  # mark safe
    dfs(x+1, y); dfs(x-1, y); dfs(x, y+1); dfs(x, y-1)

# DFS from all border 'O's
for i in range(rows):
    if grid[i][0] == 'O': dfs(i, 0)
    if grid[i][cols-1] == 'O': dfs(i, cols-1)
for j in range(cols):
    if grid[0][j] == 'O': dfs(0, j)
    if grid[rows-1][j] == 'O': dfs(rows-1, j)

# Final pass: unmarked 'O' → 'X', 'S' → 'O'
for i in range(rows):
    for j in range(cols):
        if grid[i][j] == 'O': grid[i][j] = 'X'
        elif grid[i][j] == 'S': grid[i][j] = 'O'
